#!/usr/bin/env bash
# AI generated by pi coding agent, v1.0
#
# Build the TypeScript dashboard and publish it to www/.
#
# www/ is a pure deploy target: it must only ever contain files that are meant
# to be served over HTTP. No TypeScript sources, no node_modules, no
# package.json, no tsconfig.json. The script therefore wipes www/ and copies
# exactly two things:
#
#   webapp/dist/    the Vite build output (index.html + assets)
#   webapp/api/     the PHP endpoints
#
# Usage:
#   ./scripts/deploy_web.sh
#
# Options:
#   --skip-build   reuse the existing webapp/dist (faster while iterating on CSS
#                  or on the PHP side)
#
# End of AI generated by pi coding agent, v1.0

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WEBAPP="${ROOT}/webapp"
WWW="${ROOT}/www"
DIST="${WEBAPP}/dist"
API="${WEBAPP}/api"

SKIP_BUILD=0
for argument in "$@"; do
    case "${argument}" in
        --skip-build) SKIP_BUILD=1 ;;
        -h|--help)
            sed -n '2,26p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'
            exit 0
            ;;
        *)
            echo "deploy_web: unknown option '${argument}'" >&2
            exit 2
            ;;
    esac
done

if [ ! -d "${WEBAPP}" ]; then
    echo "deploy_web: ${WEBAPP} does not exist" >&2
    exit 1
fi

# ---------------------------------------------------------------------------
# Build the frontend
# ---------------------------------------------------------------------------

if [ "${SKIP_BUILD}" -eq 0 ]; then
    echo "==> building frontend in webapp/"
    cd "${WEBAPP}"

    if [ ! -d node_modules ]; then
        npm ci
    fi

    # tsc --noEmit && vite build
    npm run build
fi

if [ ! -f "${DIST}/index.html" ]; then
    echo "deploy_web: ${DIST}/index.html is missing - run without --skip-build" >&2
    exit 1
fi

# ---------------------------------------------------------------------------
# Publish
# ---------------------------------------------------------------------------

echo "==> publishing to www/"
rm -rf "${WWW}"
mkdir -p "${WWW}/api"

cp -R "${DIST}/." "${WWW}/"

# Only PHP files are published; anything else that may end up in webapp/api
# (notes, backups) is deliberately left behind.
cp "${API}"/*.php "${WWW}/api/"

# The web server must be able to read everything but should not need to write.
chmod -R a+rX "${WWW}"

# ---------------------------------------------------------------------------
# Verification: www/ must not contain source code
# ---------------------------------------------------------------------------

echo "==> verifying www/ contains only deployable files"
unwanted="$(
    find "${WWW}" \
        \( -name '*.ts' -o -name '*.map' -o -name 'package.json' -o -name 'package-lock.json' \
           -o -name 'tsconfig.json' -o -name 'vite.config.ts' -o -name 'node_modules' \
           -o -name '.git*' -o -name '*.md' -o -name '*.ini' \) -print
)"

if [ -n "${unwanted}" ]; then
    echo "deploy_web: unexpected files in www/:" >&2
    echo "${unwanted}" >&2
    exit 1
fi

echo "==> done"
find "${WWW}" -type f | sed "s|${ROOT}/||" | sort
# End of AI generated by pi coding agent, v1.0
